"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase/client";

export default function ProtectedPage() {
  const router = useRouter();
    const supabase = createClient();
      const [loading, setLoading] = useState(true);
        const [profile, setProfile] = useState<any>(null);
          const [editing, setEditing] = useState(false);
            const [form, setForm] = useState({
                full_name: "",
                    phone: "",
                        region: "",
                            district: "",
                                commune: "",
                                    bio: "",
                                        specialties: "",
                                            years_of_experience: "",
                                              });
                                                const [message, setMessage] = useState("");

                                                  useEffect(() => {
                                                      const load = async () => {
                                                            const { data: { user } } = await supabase.auth.getUser();
                                                                  if (!user) {
                                                                          router.push("/auth/login");
                                                                                  return;
                                                                                        }
                                                                                              const { data } = await supabase
                                                                                                      .from("profiles")
                                                                                                              .select("*")
                                                                                                                      .eq("id", user.id)
                                                                                                                              .single();

                                                                                                                                    if (data) {
                                                                                                                                            setProfile(data);
                                                                                                                                                    setForm({
                                                                                                                                                              full_name: data.full_name || "",
                                                                                                                                                                        phone: data.phone || "",
                                                                                                                                                                                  region: data.region || "",
                                                                                                                                                                                            district: data.district || "",
                                                                                                                                                                                                      commune: data.commune || "",
                                                                                                                                                                                                                bio: data.bio || "",
                                                                                                                                                                                                                          specialties: data.specialties || "",
                                                                                                                                                                                                                                    years_of_experience: data.years_of_experience?.toString() || "",
                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                          setEditing(true);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                      setLoading(false);
                                                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                                                              load();
                                                                                                                                                                                                                                                                                }, []);

                                                                                                                                                                                                                                                                                  const handleSave = async (e: React.FormEvent) => {
                                                                                                                                                                                                                                                                                      e.preventDefault();
                                                                                                                                                                                                                                                                                          setMessage("");
                                                                                                                                                                                                                                                                                              const { data: { user } } = await supabase.auth.getUser();
                                                                                                                                                                                                                                                                                                  if (!user) return;

                                                                                                                                                                                                                                                                                                      const { error } = await supabase.from("profiles").upsert({
                                                                                                                                                                                                                                                                                                            id: user.id,
                                                                                                                                                                                                                                                                                                                  full_name: form.full_name,
                                                                                                                                                                                                                                                                                                                        phone: form.phone,
                                                                                                                                                                                                                                                                                                                              region: form.region,
                                                                                                                                                                                                                                                                                                                                    district: form.district,
                                                                                                                                                                                                                                                                                                                                          commune: form.commune,
                                                                                                                                                                                                                                                                                                                                                bio: form.bio,
                                                                                                                                                                                                                                                                                                                                                      specialties: form.specialties,
                                                                                                                                                                                                                                                                                                                                                            years_of_experience: form.years_of_experience
                                                                                                                                                                                                                                                                                                                                                                    ? parseInt(form.years_of_experience)
                                                                                                                                                                                                                                                                                                                                                                            : null,
                                                                                                                                                                                                                                                                                                                                                                                  updated_at: new Date().toISOString(),
                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                          if (error) {
                                                                                                                                                                                                                                                                                                                                                                                                setMessage("Erreur : " + error.message);
                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                          setMessage("Profil enregistré !");
                                                                                                                                                                                                                                                                                                                                                                                                                setEditing(false);
                                                                                                                                                                                                                                                                                                                                                                                                                      setProfile({ ...form });
                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                              if (loading) return <div className="p-8">Chargement...</div>;

                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="max-w-xl mx-auto p-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                          <h1 className="text-2xl font-bold mb-4">Mon Profil Tantsaha</h1>
<a href="/protected/home" className="text-blue-600 underline block mb-4">
        ← Hiverina any amin'ny Home
              </a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                {!editing && profile && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p><strong>Anarana:</strong> {profile.full_name}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p><strong>Téléphone:</strong> {profile.phone}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p><strong>Faritra:</strong> {profile.region} / {profile.district} / {profile.commune}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p><strong>Bio:</strong> {profile.bio}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p><strong>Fahaiza-manao:</strong> {profile.specialties}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p><strong>Taona traikefa:</strong> {profile.years_of_experience}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick={() => setEditing(true)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="mt-4 bg-black text-white px-4 py-2 rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Hanova
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {editing && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <form onSubmit={handleSave} className="space-y-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    placeholder="Anarana feno"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value={form.full_name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(e) => setForm({ ...form, full_name: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="Nomeraon-telefaonina"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={form.phone}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => setForm({ ...form, phone: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder="Faritra (Region)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={form.region}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(e) => setForm({ ...form, region: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                placeholder="District"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value={form.district}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onChange={(e) => setForm({ ...form, district: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    placeholder="Kaominina"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value={form.commune}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(e) => setForm({ ...form, commune: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <textarea
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="Bio"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={form.bio}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => setForm({ ...form, bio: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder="Fahaiza-manao"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={form.specialties}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(e) => setForm({ ...form, specialties: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="border p-2 w-full rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder="Taona traikefa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={form.years_of_experience}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(e) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setForm({ ...form, years_of_experience: e.target.value })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="submit"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className="bg-green-600 text-white px-4 py-2 rounded"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Tehirizo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {message && <p className="mt-4">{message}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }